var e = $('Workflow Error').first().json;
var rows = $input.all().map(function (i) { return i.json.telegram_user_id; }).filter(function (x) { return x; });
var ex = e.execution || {}; var wf = e.workflow || {}; var er = ex.error || {};
var msg = String(er.message || 'unknown error').slice(0, 300);
var node = String((er.node && er.node.name) || ex.lastNodeExecuted || '');
function b64(o) { return Buffer.from(JSON.stringify(o), 'utf8').toString('base64'); }
var meta = { workflow: wf.name, node: node, execution_id: ex.id };
var exid = String(ex.id || 'none').replace(/[^0-9a-zA-Z_-]/g, '');
var wn = String(wf.name || 'unknown').replace(/[^0-9a-zA-Z _-]/g, '');
var sql = "select public.nis_log('" + exid + "','" + wn + "','" + String(node).replace(/[^0-9a-zA-Z _-]/g, '') + "','error',convert_from(decode('" + b64(msg) + "','base64'),'UTF8'),convert_from(decode('" + b64(meta) + "','base64'),'UTF8')::jsonb) as r";
var text = '⚠️ <b>Workflow error</b>' + String.fromCharCode(10) + wn + ' · node: ' + node + String.fromCharCode(10) + msg.replace(/&/g, '&amp;').replace(/</g, '&lt;') + String.fromCharCode(10) + 'Execution ' + exid;
return [{ json: { sql: sql, chat_id: rows.length ? Number(rows[0]) : null, text: text } }];
